// src/orders/api.ts — mock backend over a seeded in-memory Order store with delayed, sometimes-failing Promise calls.
import type { Order, OrderDraft, OrderStatus } from "./types";
import { OrderError } from "./types";
import { isTerminal, nextStatus } from "./status";

const BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
const usedIds = new Set<string>();

export function generateOrderId(): string {
  let id = "";
  do {
    id = "ORD-";
    for (let i = 0; i < 8; i++) {
      id += BASE36[Math.floor(Math.random() * BASE36.length)];
    }
  } while (usedIds.has(id));
  usedIds.add(id);
  return id;
}

const store: Order[] = [];

export function listOrders(): Promise<Order[]> {
  return delay().then(() => [...store]);
}

export function getOrder(id: string): Promise<Order | undefined> {
  return delay().then(() => store.find((o) => o.id === id));
}

export function placeOrder(draft: OrderDraft): Promise<Order> {
  return delay().then(() => {
    if (draft.payment.cardNumber.endsWith("0000")) {
      throw new OrderError("declined");
    }
    if (draft.lines.some((line) => line.qty > 10)) {
      throw new OrderError("out_of_stock");
    }
    const order = buildOrder(draft, "pending");
    store.push(order);
    return order;
  });
}

export function cancelOrder(id: string): Promise<Order> {
  return delay().then(() => {
    const order = findOrderOrThrow(id);
    if (isTerminal(order.status)) {
      throw new Error(`order ${id} is terminal and cannot be cancelled`);
    }
    order.status = "cancelled";
    return order;
  });
}

export function advanceOrder(id: string): Promise<Order> {
  return delay().then(() => {
    const order = findOrderOrThrow(id);
    const next = nextStatus(order.status);
    if (next === null) {
      throw new Error(`order ${id} is terminal and cannot be advanced`);
    }
    order.status = next;
    return order;
  });
}

function buildOrder(draft: OrderDraft, status: OrderStatus): Order {
  return {
    id: generateOrderId(),
    createdAt: new Date().toISOString(),
    status,
    lines: [...draft.lines],
    address: draft.address,
    payment: draft.payment,
  };
}

function findOrderOrThrow(id: string): Order {
  const order = store.find((o) => o.id === id);
  if (!order) {
    throw new Error(`unknown order id: ${id}`);
  }
  return order;
}

function delay(): Promise<void> {
  const ms = 50 + Math.floor(Math.random() * 101);
  return new Promise((resolve) => setTimeout(resolve, ms));
}

const now = Date.now();
store.push(buildOrder({ ... }, "paid"));
store[0].createdAt = new Date(now - 1000 * 60 * 60 * 24).toISOString();
store.push(buildOrder({ ... }, "shipped"));
store[1].createdAt = new Date(now - 1000 * 60 * 60 * 12).toISOString();
```

