```ts
// src/orders/storage.ts — Versioned, validated read/write of the order list to localStorage.
import type { Order, OrderStatus } from "./types";

const STORAGE_VERSION = 1;
const MIN_QTY = 1;
const MAX_QTY = 99;
const VALID_STATUSES: readonly string[] = ["pending", "paid", "shipped", "delivered", "cancelled"];

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isString(value: unknown): value is string {
  return typeof value === "string";
}

function isOrderStatus(value: unknown): value is OrderStatus {
  return isString(value) && VALID_STATUSES.includes(value);
}

function isOrderLine(value: unknown): value is { productId: string; name: string; price: number; qty: number } {
  return (
    isRecord(value) &&
    isString(value.productId) &&
    isString(value.name) &&
    typeof value.price === "number" &&
    typeof value.qty === "number"
  );
}

function clampQty(qty: number): number {
  return Math.min(Math.max(qty, MIN_QTY), MAX_QTY);
}

function parseOrder(value: unknown): Order | null {
  if (
    !isRecord(value) ||
    !isString(value.id) ||
    !isString(value.createdAt) ||
    !Array.isArray(value.lines) ||
    !isRecord(value.address) ||
    !isRecord(value.payment)
  ) {
    return null;
  }

  const address = value.address;
  if (!isString(address.name) || !isString(address.street) || !isString(address.city) || !isString(address.postalCode) || !isString(address.country)) {
    return null;
  }

  const payment = value.payment;
  if (!isString(payment.cardNumber) || !isString(payment.expiry) || !isString(payment.nameOnCard)) {
    return null;
  }

  const status: OrderStatus = isOrderStatus(value.status) ? value.status : "pending";

  const lines: Order["lines"] = [];
  for (const line of value.lines) {
    if (!isOrderLine(line)) continue;
    lines.push({ productId: line.productId, name: line.name, price: line.price, qty: clampQty(line.qty) });
  }

  return {
    id: value.id,
    createdAt: value.createdAt,
    status,
    lines,
    address: {
      name: address.name,
      street: address.street,
      city: address.city,
      postalCode: address.postalCode,
      country: address.country,
    },
    payment: {
      cardNumber: payment.cardNumber,
      expiry: payment.expiry,
      nameOnCard: payment.nameOnCard,
    },
  };
}

/**
 * localStorage key under which the versioned orders envelope is stored.
 */
export const STORAGE_KEY: string = "ministore:orders";

/**
 * Reads and parses the STORAGE_KEY envelope. Returns [] if the key is absent, the JSON is invalid, or the envelope shape is wrong. Drops any order missing a required field (id, createdAt, status, lines, address, payment) or with a wrong-typed one. For surviving orders, clamps every line's qty into 1..99 and replaces an unrecognized status string with "pending".
 */
export function loadOrders(): Order[] {
  const raw = localStorage.getItem(STORAGE_KEY);
  if (raw === null) return [];

  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return [];
  }

  if (!isRecord(parsed) || !Array.isArray(parsed.orders)) return [];

  const orders: Order[] = [];
  for (const entry of parsed.orders) {
    const order = parseOrder(entry);
    if (order !== null) orders.push(order);
  }
  return orders;
}

/**
 * Writes { version, orders } as JSON to STORAGE_KEY, overwriting any existing value.
 */
export function saveOrders(orders: Order[]): void {
  localStorage.setItem(STORAGE_KEY, JSON.stringify({ version: STORAGE_VERSION, orders }));
}

/**
 * Removes STORAGE_KEY from localStorage entirely.
 */
export function clearOrders(): void {
  localStorage.removeItem(STORAGE_KEY);
}
```

FINDING: The tests set `globalThis.localStorage` to a `MemoryStorage` in `beforeEach`, so `loadOrders`/`saveOrders` must use the ambient global `localStorage` (not a captured reference) to see the mock.

