export function subtotal(order: Order): number {
  return order.lines.reduce((sum, line) => sum + line.price * line.qty, 0);
}

export function shipping(order: Order): number {
  return subtotal(order) < 50 ? 7.99 : 0;
}

export function tax(order: Order, rate: number): number {
  return Math.round(subtotal(order) * rate * 100) / 100;
}

export function total(order: Order): number {
  return subtotal(order) + shipping(order);
}

export function formatOrderTotal(order: Order, locale: string): string {
  return new Intl.NumberFormat(locale, { style: "currency", currency: "USD" }).format(total(order));
}
