```tsx
// src/orders/OrdersPage.tsx — the Orders screen: list + empty state + selected-order detail panel with totals breakdown.
import { useState, type JSX } from "react";
import type { Order } from "./types";
import { useOrders } from "./useOrders";
import { subtotal, shipping, tax, total, formatOrderTotal } from "./totals";
import { transitionsFor, statusLabel } from "./status";
import OrderRow from "./OrderRow";

const TAX_RATE = 0.0825;

const usd = (n: number): string =>
  new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(n);

type Totals = { subtotal: number; shipping: number; tax: number; total: number };

function orderTotals(order: Order): Totals {
  return {
    subtotal: subtotal(order),
    shipping: shipping(order),
    tax: tax(order, TAX_RATE),
    total: total(order),
  };
}

function DetailPanel(props: { order: Order; busy: boolean; onCancel: (id: string) => void; onAdvance: (id: string) => void }): JSX.Element {
  const { order, busy, onCancel, onAdvance } = props;
  const totals = orderTotals(order);
  return (
    <aside className="order-detail">
      <header className="detail-header">
        <div>
          <h3>{order.id}</h3>
          <p className="detail-meta">
            {new Date(order.createdAt).toLocaleString("en-US")} · {statusLabel(order.status)}
          </p>
        </div>
        <strong className="detail-total">{formatOrderTotal(order, "en-US")}</strong>
      </header>
      <h4>Items</h4>
      <ul className="order-lines">
        {order.lines.map((line) => (
          <li key={line.productId} className="line">
            <span className="line-name">{line.name}</span>
            <span className="line-qty">×{line.qty}</span>
            <span className="line-price">{usd(line.price * line.qty)}</span>
          </li>
        ))}
      </ul>
      <dl className="order-totals">
        <div className="total-row">
          <dt>Subtotal</dt>
          <dd>{usd(totals.subtotal)}</dd>
        </div>
        <div className="total-row">
          <dt>Shipping</dt>
          <dd>{usd(totals.shipping)}</dd>
        </div>
        <div className="total-row">
          <dt>Tax</dt>
          <dd>{usd(totals.tax)}</dd>
        </div>
        <div className="total-row grand">
          <dt>Total</dt>
          <dd>{usd(totals.total)}</dd>
        </div>
      </dl>
      <div className="detail-actions">
        {transitionsFor(order.status).map((to) =>
          to === "cancelled" ? (
            <button key={to} className="ghost" disabled={busy} onClick={() => onCancel(order.id)}>
              Cancel
            </button>
          ) : (
            <button key={to} className="checkout" disabled={busy} onClick={() => onAdvance(order.id)}>
              Advance
            </button>
          )
        )}
      </div>
    </aside>
  );
}

/**
 * Calls useOrders() and renders: an empty state when orders.length === 0; otherwise a list of OrderRow, one per order, tracking a selected id in local state. The selected order's lines and totals breakdown (subtotal/shipping/tax/total via totals.ts) render in a detail panel. Each row's Cancel/Advance handlers call useOrders().cancel/advance and pass `busy` while that order's call is pending.
 */
export default function OrdersPage(): JSX.Element {
  const { orders, error, cancel, advance } = useOrders();
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [busyId, setBusyId] = useState<string | null>(null);

  const selected = orders.find((o) => o.id === selectedId) ?? null;

  const runAction = async (id: string, action: (id: string) => Promise<void>): Promise<void> => {
    setBusyId(id);
    try {
      await action(id);
    } finally {
      setBusyId(null);
    }
  };

  if (orders.length === 0) {
    return (
      <section className="orders-page">
        <header className="orders-header">
          <h2>Orders</h2>
          {error && (
            <p className="orders-error" role="alert">
              {error.message}
            </p>
          )}
        </header>
        <p className="orders-empty">No orders yet. Placed orders will show up here.</p>
      </section>
    );
  }

  return (
    <section className="orders-page">
      <header className="orders-header">
        <h2>Orders</h2>
        {error && (
          <p className="orders-error" role="alert">
            {error.message}
          </p>
        )}
      </header>
      <div className="orders-layout">
        <ul className="orders-list">
          {orders.map((order) => (
            <OrderRow
              key={order.id}
              order={order}
              selected={order.id === selectedId}
              onSelect={(id) => setSelectedId(id)}
              onCancel={(id) => void runAction(id, cancel)}
              onAdvance={(id) => void runAction(id, advance)}
              busy={busyId === order.id}
            />
          ))}
        </ul>
        {selected ? (
          <DetailPanel
            order={selected}
            busy={busyId === selected.id}
            onCancel={(id) => void runAction(id, cancel)}
            onAdvance={(id) => void runAction(id, advance)}
          />
        ) : (
          <aside className="order-detail">
            <p className="orders-empty">Select an order to see its lines and totals.</p>
          </aside>
        )}
      </div>
    </section>
  );
}
